namespace App\Livewire;

use Livewire\Component;
use App\Models\Order;
use Illuminate\Support\Facades\Auth;

class ManageOrderShipping extends Component
{
    public int $orderId;
    public string $street = '';
    public string $city = '';
    public string $postalCode = '';

    public function updateAddress()
    {
        $order = Auth::user()->orders()->findOrFail($this->orderId);
        $this->authorize('updateShipping', $order);

        $order->update([
            'shipping_street' => $this->street,
            'shipping_city' => $this->city,
            'shipping_postal_code' => $this->postalCode
        ]);
    }

    public function render()
    {
        return view('livewire.manage-order-shipping');
    }
}
